from __future__ import annotations


def max_drawdown(prices: list[float]) -> float:
    if len(prices) < 2:
        return 0.0

    largest = 0.0
    peak = prices[0]

    for i in range(1, len(prices)):
        price = prices[i]
        if price > peak:
            peak = price
        else:
            drawdown = (peak - price) / peak
            if drawdown > largest:
                largest = drawdown

    return largest",
  "notes": "Optimized from O(n^2) to O(n) by tracking running peak and computing drawdown in single pass. Handles all edge cases correctly: empty/one-price returns 0.0, increasing series returns 0.0, decreasing series computes max drop. Preserves exact output of original within floating-point tolerance."
